REGIONS=[]
def add(id,name,family,branch,cluster,level,source,points,note='',holes=None):
 REGIONS.append(dict(id=id,name=name,family=branch,branch=branch,cluster=cluster,
  subcluster=name if level=='小片' else None,level=level,source=source,
  parentId=None,points=points,holes=holes or [],evidenceNote=note))
def pts(s): return [list(map(float,p.split(','))) for p in s.split()]

